use std::sync::Arc;
fn main(){
let source="---- MODULE AliasAudit ----\nEXTENDS Naturals\nCONSTANT Gate\nVARIABLE x\nContainer(v) == LET Hidden == TRUE IN v\nInit == x=0\nNext == x<3 /\\ x'=x+1\n====\n";
let analysis=dive_sema::analyze_source("AliasAudit.tla",source,&Default::default());assert!(analysis.accepted());let ir=dive_ir::lower(&analysis).unwrap();let selected=ir.defs().iter().position(|d|d.name=="Hidden").unwrap();let parent=ir.defs().iter().position(|d|d.name=="Init").unwrap();let mut encoded=serde_json::to_value(&ir).unwrap();encoded["modules"][ir.root().index()]["standard"]=serde_json::json!(true);let body=ir.defs()[selected].body.index();let mut call=encoded["exprs"][body].clone();let new=encoded["exprs"].as_array().unwrap().len();call["expr"]=serde_json::json!({"Apply":{"callee":{"Std":"TlcPrintT"},"args":[{"Expr":{"expr":body,"pass":"Direct"}}]}});call["effects"]=serde_json::json!(5);encoded["exprs"].as_array_mut().unwrap().push(call);encoded["defs"][selected]["body"]=serde_json::json!(new);encoded["defs"][selected]["effects"]=serde_json::json!(5);encoded["modules"][ir.root().index()]["context"].as_array_mut().unwrap().push(serde_json::json!(["Alias",{"Def":selected}]));std::fs::write("arena.json",serde_json::to_vec_pretty(&encoded).unwrap()).unwrap();let ir:Arc<dive_ir::Ir>=Arc::new(serde_json::from_value(encoded).unwrap());println!("authority {:?}",dive_eval::validate_ir(&ir));let cfg=dive_config::parse("CONSTANT Gate <- Alias\nINIT Init\nNEXT Next\nCHECK_DEADLOCK FALSE\n").into_config().unwrap();let out=dive_check::checkpoint::check(&ir,&cfg,&dive_check::CheckOptions::tlc(0,7),&dive_check::checkpoint::Request{path:"audit.cp".into(),action:dive_check::checkpoint::Action::PauseAfterLevels(0),counters:dive_check::checkpoint::Counters::Retain,config_source_sha256:None});println!("result {out:?}");}
